import type { Href } from "expo-router";

/**
 * expo-router typed-route literals are code-generated by the dev server into
 * `.expo/types`. App-built dynamic hrefs (e.g. `/ip/123`) are validated at
 * runtime by the router; cast them here so screens stay clean and don't depend
 * on generated types being present at lint time.
 */
export function toHref(path: string): Href {
  return path as Href;
}
